SELECT MAX(p.instability_score) AS max_instability_score, CAST(COUNT(DISTINCT CASE WHEN p.death_date IS NOT NULL THEN p.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT p.subject_id), 0) AS mortality_rate, AVG(p.length_of_stay) AS average_length_of_stay, SUM(CASE WHEN l.itemid IN (SELECT itemid FROM d_labitems WHERE category = 'Critical') THEN 1 ELSE 0 END) / NULLIF(COUNT(DISTINCT p.subject_id), 0) AS critical_labs_ratio FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN labevents l ON a.subject_id = l.subject_id AND a.hadm_id = l.hadm_id WHERE p.gender = 'M' AND EXTRACT(YEAR FROM p.dob) = 1980 AND EXTRACT(YEAR FROM a.admittime) BETWEEN 2025 AND 2026 AND p.age >= 75 AND p.age <= 85 AND p.had_hepatic_failure = TRUE AND a.dischtime - a.admittime <= 48 GROUP BY p.subject_id;